<div class="page-heading"><div><p class="eyebrow">Finance</p><h1>Payments</h1><p>Record manual or externally processed payments and manage their lifecycle.</p></div><a class="btn btn-primary" href="<?= site_url('admin/payments/new') ?>">Record payment</a></div>
<section class="admin-card"><div class="ledger-note"><strong>Payment boundary:</strong><span>This screen records results from manual or configured providers. It does not charge a card directly.</span></div><form class="filter-bar" action="<?= site_url('admin/payments') ?>" method="get"><input class="form-control" name="q" type="search" value="<?= esc($filters['q'], 'attr') ?>" placeholder="Payment, booking, or customer" aria-label="Search payments"><select class="form-select" name="status" aria-label="Filter status"><option value="">All statuses</option><?php foreach (['pending', 'completed', 'failed', 'refunded'] as $status): ?><option value="<?= $status ?>"<?= $filters['status'] === $status ? ' selected' : '' ?>><?= ucfirst($status) ?></option><?php endforeach ?></select><button class="btn btn-dark" type="submit">Filter</button><?php if (array_filter($filters) !== []): ?><a class="btn btn-link" href="<?= site_url('admin/payments') ?>">Clear</a><?php endif ?></form>
