 <?= esc($payment['currency'] . ' ' . number_format((float) $payment['amount'], 2), 'attr') ?>? This adds an immutable negative ledger entry." data-confirm-title="Refund payment?" data-confirm-button="Yes, record refund" data-confirm-danger="true" data-loading-title="Recording refund"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger" type="submit">Refund</button></form><?php else: ?>—<?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
